meta.vocabulary:
@works_in predicate
  args subject:entity object:entity
  description "the subject works in the department named by the object (workshop, logistics, office or sales)"
@full_time_employee predicate
  args subject:entity
  description "whether the subject is a full-time employee of BTC: a person employed by BTC on a contract for 35 or more hours per week"
@tenure_months predicate
  args subject:entity object:integer
  description "the subject's tenure in complete calendar months as of the reference date 2026-03-01; calculated from the start date, never rounded, fractional months do not count toward tenure bands; the calendar computation itself is not expressed in this compilation and is supplied as data"
@may_work_remotely predicate
  args subject:entity
  description "whether the subject may work remotely"

@trip predicate
  args subject:entity
  description "whether the subject is a period of travel and activity"
@trip_away_from_main_office predicate
  args subject:entity
  description "whether the subject trip takes place away from the main office"
@trip_work_purpose predicate
  args subject:entity
  description "whether the subject trip serves work purposes"
@trip_duration_days predicate
  args subject:entity object:integer
  description "the duration of the subject trip in consecutive calendar days; supplied as data, calendar arithmetic is not computed"
@requires_approval_by predicate
  args subject:entity object:entity
  description "whether the subject (an expense reimbursement, claim or trip) must be approved by the role or department named by the object"

@ocean_depth_min_km predicate
  args subject:entity object:integer
  description "the lower end in kilometers of the depth of the ocean beneath the subject's ice shell as stated by the source's range; at least how deep the ocean is"

@has_abundant_water predicate
  args subject:entity
  description "the subject has abundant water; whether it does"

@named_for predicate
  args subject:entity object:entity
  description "the subject is named for the named person; who the subject is named for"

@ocean_may_have_existed_for_years predicate
  args subject:entity object:integer
  description "the subject's ocean may have existed for the named number of years, approximately 4 billion years, the entirety of the solar system's history; how long it may have existed"

@energy_mostly_from predicate
  args subject:entity object:entity
  description "most of the energy used on the subject comes from the named source; where most of it comes from"

@building_block_element predicate
  args subject:entity object:entity
  description "the named chemical element is among the subject's building blocks of life; the source's list is open, it says 'including'"

@ocean_depth_max_km predicate
  args subject:entity object:integer
  description "the upper end in kilometers of the depth of the ocean beneath the subject's ice shell as stated by the source's range; at most how deep the ocean is"

@works_in predicate
  args subject:entity object:entity
  description "the subject works in the department named by the object (workshop, logistics, office or sales)"
@employee predicate
  args subject:entity
  description "whether the subject is an employee of BTC (full-time or part-time)"
@tenure_months predicate
  args subject:entity object:integer
  description "the subject's tenure in complete calendar months as of the reference date 2026-03-01; calculated from the start date, never rounded, fractional months do not count toward tenure bands; the calendar computation itself is not expressed in this compilation and is supplied as data"
@approval predicate
  args subject:entity topic:entity object:entity
  description "whether the subject has the approval of the approver named by the object (for example department_head) for the topic (for example remote_work)"
@may_work_remotely predicate
  args subject:entity
  description "whether the subject may work remotely"

@formed_from_leftovers_of predicate
  args subject:entity object:entity
  description "the subject formed out of leftover material after the object condensed from the initial cloud of gas and dust surrounding the sun, early in the history of the solar system; whether the subject formed from the object's leftover material"

@expense_item predicate
  args subject:entity
  description "whether the subject is a single work-related expense item submitted for reimbursement"
@expense_amount predicate
  args subject:entity object:integer
  description "the cost of the subject expense item in credits"
@expense_item_max predicate
  args subject:entity object:integer
  description "the maximum amount in credits which a single expense item of the subject organisation may not exceed"
@reimbursable predicate
  args subject:entity
  description "whether the subject expense item is eligible for reimbursement"

@ice_shell_thickness_max_km predicate
  args subject:entity object:integer
  description "the upper end in kilometers of the subject's ice shell thickness as stated by the source's range; at most how thick the ice shell is"

@part_time_employee predicate
  args subject:entity
  description "whether the subject is a part-time employee of BTC: a person employed by BTC on a contract for fewer than 35 hours per week"
@annual_leave_days predicate
  args subject:entity object:integer
  description "how many days of paid annual leave per year the subject receives"

@age_million_years predicate
  args subject:entity object:integer
  description "the subject's age in millions of years, about the same age as the rest of the solar system (the source says about 4.5 billion years); how old the subject is"

@roman_name_of predicate
  args subject:entity object:entity
  description "the subject, a god of Greek mythology, is the same god as the named one in Roman mythology; which god he is in Roman mythology"
